import { test, expect } from '@playwright/test';

test.describe('Search Result Race Conditions', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display the latest search result when multiple requests are made concurrently', async ({ page }) => {
    // Setup: intercept the search API
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // First request: user types "playwright" and hits enter
    const searchInput = page.getByPlaceholder('Search');
    await searchInput.fill('playwright');
    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for the initial result to load
    const resultContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultContainer).toBeVisible();

    // Second request: user types "playwright" again and hits enter
    await searchInput.fill('playwright');
    await searchButton.click();

    // Wait for the second result to load
    await expect(resultContainer).toBeVisible();

    // Verify the latest result is displayed
    const latestResult = page.getByText('Playwright TypeScript');
    await expect(latestResult).toBeVisible();

    // Verify the first result is no longer visible
    const firstResult = page.getByText('Playwright Playwright');
    await expect(firstResult).not.toBeVisible();
  });

  test('should handle race conditions and display the correct result when search is interrupted', async ({ page }) => {
    // Setup: intercept the search API
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // First request: user types "playwright" and hits enter
    const searchInput = page.getByPlaceholder('Search');
    await searchInput.fill('playwright');
    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for the initial result to load
    const resultContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultContainer).toBeVisible();

    // Second request: user types "playwright" again and hits enter
    await searchInput.fill('playwright');
    await searchButton.click();

    // Wait for the second result to load
    await expect(resultContainer).toBeVisible();

    // Third request: user types "playwright" again and hits enter
    await searchInput.fill('playwright');
    await searchButton.click();

    // Wait for the third result to load
    await expect(resultContainer).toBeVisible();

    // Verify the latest result is displayed
    const latestResult = page.getByText('Playwright TypeScript');
    await expect(latestResult).toBeVisible();

    // Verify the first result is no longer visible
    const firstResult = page.getByText('Playwright Playwright');
    await expect(firstResult).not.toBeVisible();

    // Verify the second result is still visible
    const secondResult = page.getByText('Playwright Playwright');
    await expect(secondResult).toBeVisible();
  });
});
